// Differential runner: compares /output/test15.mjs against the Python executable.
// Usage:
//   node diff_vectors.mjs            # replay /workspace/harness/vectors.json (stdout+code)
//   node diff_cli.mjs                # replay /workspace/harness/cli_cases.json (stdout+stderr+code)
//   node diff_fuzz.mjs [n] [seed]    # fresh random cases, live-compare both programs
import { execFileSync } from 'node:child_process';

export const EXE = '/workspace/dataset/test15_executable';
export const JS = '/output/test15.mjs';

// Run a program with the given argv. Byte-exact capture via latin1.
// rawArgs: array of strings OR array of Buffers (Buffers let us send invalid UTF-8).
export function run(cmd, args, argv, env) {
  try {
    const stdout = execFileSync(cmd, [...args, ...argv], {
      encoding: 'latin1',
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 1 << 24,
      env: { ...process.env, ...(env || {}) },
    });
    return { stdout, stderr: '', code: 0 };
  } catch (e) {
    if (e.code === 'ENOENT') throw e;
    return {
      stdout: String(e.stdout ?? ''),
      stderr: String(e.stderr ?? ''),
      code: e.status === null || e.status === undefined ? -1 : e.status,
    };
  }
}

export const runPy = (argv, env) => run(EXE, [], argv, env);
export const runJs = (argv, env) => run('node', [JS], argv, env);

// Normalizes the parts of stderr that cannot be reproduced byte-for-byte:
//   - the PyInstaller pid: "[PYI-1234:ERROR]"  -> "[PYI-PID:ERROR]"
//   - the program name emitted by argparse (test15_executable vs test15.mjs)
export function normalizeStderr(s) {
  return s
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
    .replace(/\btest15_executable\b/g, '<prog>')
    .replace(/\btest15\.mjs\b/g, '<prog>');
}

export function report(name, failures, total) {
  const pass = total - failures.length;
  console.log(`\n[${name}] ${pass}/${total} passed, ${failures.length} failed`);
  for (const f of failures.slice(0, 20)) {
    console.log('--------------------------------------------------');
    console.log('argv    : ' + JSON.stringify(f.argv));
    console.log('field   : ' + f.field);
    console.log('expected: ' + JSON.stringify(f.expected));
    console.log('actual  : ' + JSON.stringify(f.actual));
  }
  if (failures.length > 20) console.log(`... and ${failures.length - 20} more`);
  return failures.length === 0;
}
